	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/query/v2/catalog", wrapper.GetAdvancedQueryCatalog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/query/v2/executions", wrapper.ExecuteAdvancedQueryPlan)
